// ─── i18n SYSTEM — dankcharts.fm ──────────────────────────────────────────────
// Supported languages: en · es · pt-BR · pt-PT
// AI-generated translations (es / pt-BR / pt-PT) — review & polish as needed
//
// Only English lives in this file. Each other language is its own file,
// translations.<lang>.js (2026-11-03): all four together were ~1.1MB, and a
// phone had to download and parse every one of them before the app started.
// - On page load, a small inline script right after this file's <script> tag
//   (index.html, setup-guide.html) writes a tag for the saved language, so it
//   still runs before app.js and the first paint is already in that language.
// - Picking a language later fetches its file first (dcEnsureLang), then
//   setLanguage() carries on as before.
// - Until a file is in (or if it fails), t() falls back to English per key.
// When editing a language file, bump DC_I18N_V in BOTH inline scripts.

let currentLang = 'en';

// Every language the site offers. TRANSLATIONS[lang] exists for each from the
// start (empty until its file loads), so checks like "is this a language we
// have" no longer depend on whether the file is loaded yet.
const DC_LANGS = ['en', 'es', 'pt-BR', 'pt-PT'];
// Which language files have run. English is this file.
const DC_I18N_LOADED = { en: true };
const _dcI18nLoading = {};

/* Calls done() once lang's words are in, or its file failed to load (then the
   page simply stays in English for the missing words). */
function dcEnsureLang(lang, done) {
  if (DC_I18N_LOADED[lang] || !DC_LANGS.includes(lang)) { done(); return; }
  if (_dcI18nLoading[lang]) { _dcI18nLoading[lang].push(done); return; }
  _dcI18nLoading[lang] = [done];
  const s = document.createElement('script');
  s.src = 'translations.' + lang + '.js?v=' + (window.DC_I18N_V || 1);
  const finish = () => {
    const cbs = _dcI18nLoading[lang] || [];
    delete _dcI18nLoading[lang];
    cbs.forEach(cb => cb());
  };
  s.onload = finish;
  s.onerror = finish;
  document.head.appendChild(s);
}

