// ─── HELPER: get translated string with optional variable substitution ─────────
// Usage:  t('key')  or  t('key', { n: 5, date: 'Jan 1' })
function t(key, vars) {
  const dict = TRANSLATIONS[currentLang] || TRANSLATIONS.en;
  const str = (dict[key] !== undefined) ? dict[key]
    : (TRANSLATIONS.en[key] !== undefined ? TRANSLATIONS.en[key] : key);
  if (!vars) return str;
  return str.replace(/\{\{(\w+)\}\}/g, (_, k) => (vars[k] !== undefined ? vars[k] : `{{${k}}}`));
}

// ─── HELPER: plural unit word ─────────────────────────────────────────────────
// Usage: `${n} ${tUnit('plays', n)}`  →  "3 plays" / "3 reproducciones"
function tUnit(key, n) {
  return t(n === 1 ? key + '_one' : key + '_other');
}

// ─── HELPER: number + unit ────────────────────────────────────────────────────
// Usage: tCount('plays', 3)  →  "3 plays" / "3 reproducciones"
function tCount(key, n) {
  return `${n.toLocaleString()} ${tUnit(key, n)}`;
}

// ─── HELPER: number + unit with portrait-mobile abbreviation ─────────────────
// Returns dual-span HTML so CSS can swap the unit word on narrow portrait screens.
// The unit always sits in a .cnt-unit span, so a narrow column (the chart
// table's Plays on phones, phase 7 step 7) can hide it and keep the number.
function tCountHtml(key, n) {
  const unit = tUnit(key, n);
  const mobileUnit = t(n === 1 ? key + '_one_mobile' : key + '_other_mobile');
  const count = n.toLocaleString();
  if (unit === mobileUnit) return `${count}<span class="cnt-unit"> ${unit}</span>`;
  return `${count}<span class="cnt-unit"> <span class="th-plays-full">${unit}</span><span class="th-plays-short">${mobileUnit}</span></span>`;
}

// ─── HELPER: update button label (On/Off state) ──────────────────────────────
// Usage: updateLabelButton(elemId, isOn)  →  updates button text based on state
function updateLabelButton(elemId, isOn) {
  const btn = document.getElementById(elemId);
  if (btn) {
    const label = isOn ? t('labels_on') : t('labels_off');
    // The Stats charts' buttons are icons (phase 9): keep the icon, put the
    // state in the tooltip, the screen-reader name and aria-pressed.
    if (btn.classList.contains('graph-tool')) {
      btn.title = label;
      btn.setAttribute('aria-label', label);
      btn.setAttribute('aria-pressed', isOn ? 'true' : 'false');
    } else {
      btn.textContent = label;
    }
    btn.classList.toggle('active', isOn);
  }
}

// ─── APPLY i18n TO STATIC DOM ELEMENTS ───────────────────────────────────────
// Elements with data-i18n="key"              → textContent updated
// Elements with data-i18n-placeholder="key"  → placeholder attribute updated
// Elements with data-i18n-title="key"        → title attribute updated
// Elements with data-i18n-raw-th="key"       → raw table TH (preserves sort-arrow span)
function updateMastheadDynamic() {
  const name = localStorage.getItem('dc_display_name') || '';
  const firstDate = window.firstScrobbleDate;
  const year = firstDate ? firstDate.getFullYear() : new Date().getFullYear();

  // English needs the possessive ("Alex's", "Chris'"); the other languages use "de {{name}}"
  // and ignore the possessive, so both are handed to every string.
  const possessive = name ? (name.match(/s$/i) ? name + "'" : name + "'s") : '';

  // The footer line follows the display name from Settings when there is one,
  // "Your…" when there isn't.
  const footEl = document.querySelector('[data-i18n="footer_line1"]');
  if (footEl) {
    footEl.textContent = t(name ? 'footer_line1' : 'footer_line1_default', { name, possessive, year });
  }

  // And so does the browser tab / search-result headline. Nobody visiting without a
  // display name should ever see someone else's name here.
  document.title = t(name ? 'page_title' : 'page_title_default', { name, possessive, year });
}

function applyI18n() {
  document.querySelectorAll('[data-i18n]').forEach(el => {
    // The footer line carries the display name and the first-scrobble year, so it is
    // stamped by updateMastheadDynamic() below instead of with the raw template.
    if (el.dataset.i18n === 'footer_line1') return;
    // #syncStatus carries a live status set by app.js (sync results, page counters,
    // errors…). Once one has been set, re-stamping the static placeholder here would
    // clobber it — e.g. a language switch used to permanently replace "✓ Synced" with
    // "Connecting to Google Sheets…" even for Last.fm/CSV users.
    if (el.id === 'syncStatus' && typeof _lastSyncStatusMsg !== 'undefined' && _lastSyncStatusMsg) return;
    el.textContent = t(el.dataset.i18n);
  });
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    el.innerHTML = t(el.dataset.i18nHtml);
  });
  updateMastheadDynamic();
  document.querySelectorAll('[data-i18n-aria-label]').forEach(el => {
    el.setAttribute('aria-label', t(el.dataset.i18nAriaLabel));
  });
  // Main tab tooltips are built from their (now translated) labels
  if (typeof window.dcRefreshMainTabTitles === 'function') window.dcRefreshMainTabTitles();
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    el.placeholder = t(el.dataset.i18nPlaceholder);
  });
  // aria-label only (no tooltip), for groups and icon buttons
  document.querySelectorAll('[data-i18n-aria]').forEach(el => {
    el.setAttribute('aria-label', t(el.dataset.i18nAria));
  });
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    el.title = t(el.dataset.i18nTitle);
    if (el.hasAttribute('aria-label')) el.setAttribute('aria-label', el.title);
  });
  // Raw data table headers keep their inner sort-arrow span — only update the text node
  document.querySelectorAll('[data-i18n-raw-th]').forEach(el => {
    const arrow = el.querySelector('.sort-arrow');
    el.textContent = t(el.dataset.i18nRawTh);
    if (arrow) el.appendChild(arrow);
  });
  document.querySelectorAll('[data-i18n-with-n]').forEach(el => {
    el.textContent = t(el.dataset.i18nWithN, { n: el.dataset.i18nN });
  });
  // Row-2 nav toggle swaps between two keys based on open/collapsed state,
  // so it can't be a plain data-i18n — re-derive it from current DOM state instead.
  const navToggleLabel = document.querySelector('#periodNavToggle .period-nav-toggle-label');
  const navRow2 = document.getElementById('periodNavRow2');
  if (navToggleLabel && navRow2) {
    const isOpen = !navRow2.classList.contains('nav-row2-collapsed');
    navToggleLabel.textContent = t(isOpen ? 'nav_toggle_less' : 'nav_toggle_more');
  }
  // Collapse All / Expand All swaps between two keys the same way — re-derive from state
  if (typeof syncCollapseAllBtn === 'function') syncCollapseAllBtn();
}

// ─── LANGUAGE SWITCHER ────────────────────────────────────────────────────────
// The language most recently asked for; a slow file for an earlier pick must
// not switch the page back once it arrives.
let _dcLangWanted = null;
function setLanguage(lang) {
  if (!DC_LANGS.includes(lang)) lang = 'en';
  // Fetch the language's words first (only the first time it is picked)
  if (!DC_I18N_LOADED[lang]) {
    _dcLangWanted = lang;
    dcEnsureLang(lang, () => { if (_dcLangWanted === lang) setLanguage(lang); });
    return;
  }
  _dcLangWanted = lang;
  currentLang = lang;
  try { localStorage.setItem('dankcharts-lang', lang); } catch (e) { }
  document.documentElement.lang = lang;

  // Update active button state
  document.querySelectorAll('.lang-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.lang === lang);
  });

  // Sync mobile lang trigger flag icon
  const langGroupFlag = document.getElementById('langGroupFlag');
  if (langGroupFlag) {
    const activeBtn = document.querySelector('.lang-btn[data-lang="' + lang + '"]');
    if (activeBtn) langGroupFlag.textContent = activeBtn.textContent.trim().split(' ')[0];
  }
  // Top bar language button shows the code instead of a flag (phase 5)
  const langGroupCode = document.getElementById('langGroupCode');
  if (langGroupCode) langGroupCode.textContent = lang.toUpperCase();

  // Update static DOM strings
  applyI18n();
  // Settings text that depends on state (Last.fm connection, script viewer)
  if (typeof refreshSettingsI18n === 'function') refreshSettingsI18n();

  // The What's New list is built once and cached, so it has to be told to
  // rebuild (and fetch the new language's entries) rather than being re-stamped.
  if (typeof dcClOnLanguageChange === 'function') dcClOnLanguageChange();

  // Events cards carry dates and release types in the language: draw them again
  if (typeof _evReRenderSection === 'function') Object.keys(EV_GRID_IDS).forEach(_evReRenderSection);
  if (typeof _renderEventsToday === 'function') _renderEventsToday();
  if (typeof _renderEventsLists === 'function') _renderEventsLists();
  // the status lines behind ⓘ
  if (typeof _evRepaintStatuses === 'function') _evRepaintStatuses();
  // the Awards page (cards, stats, category list, an open ceremony or picker)
  if (typeof awardsOnLanguageChange === 'function') awardsOnLanguageChange();
  // Your Soundtrack (its chapter headlines and an open "Play your year")
  if (typeof stOnLanguageChange === 'function') stOnLanguageChange();
  // The Charts Guide (its words come from charts-guide-i18n.js)
  if (typeof dcRenderChartsGuideView === 'function' && typeof currentPeriod !== 'undefined' && currentPeriod === 'chartsguide') dcRenderChartsGuideView();
  // Playlists (its page is drawn in JS)
  if (typeof dcRenderPlaylistsView === 'function' && typeof currentPeriod !== 'undefined' && currentPeriod === 'playlists') dcRenderPlaylistsView();
  // and the calendar ("+N more", the Day view's cards)
  if (typeof _eventsCalendarData !== 'undefined' && _eventsCalendarData) renderEventsCalendar(_eventsCalendarData, eventsCalendarYear, eventsCalendarMonth);

  // Longer words can overflow the top bar; tighten it if they do
  if (typeof dcFitTopbar === 'function') dcFitTopbar();

  // The Records dropdown copies the active sub-tab's name; copy it again
  if (typeof recNavUpdatePicker === 'function') recNavUpdatePicker();

  // The now strip is not part of renderAll(); redo its words. The in-a-row
  // run and "Last played…" (renderStreakBanner), the ON AIR song and its
  // chips (refreshNowPlayingStats), then the listening streak.
  if (typeof allPlays !== 'undefined' && allPlays && allPlays.length) {
    if (typeof renderStreakBanner === 'function') renderStreakBanner();
    if (typeof refreshNowPlayingStats === 'function') refreshNowPlayingStats();
  }
  if (typeof renderNowStripDayStreak === 'function' && typeof _nsDay !== 'undefined' && _nsDay) {
    renderNowStripDayStreak(_nsDay.count, _nsDay.pb);
  }

  // Re-render the full chart so date labels, period header, and section titles update
  if (typeof renderAll === 'function' && typeof allPlays !== 'undefined' && allPlays && allPlays.length > 0) {
    // Snapshot open chart run panels before re-render wipes the DOM
    const openPanels = [];
    document.querySelectorAll('.cr-row.open .cr-panel[data-crtype][data-crkey]').forEach(panel => {
      openPanels.push({ crtype: panel.dataset.crtype, crkey: panel.dataset.crkey });
    });

    // Bubbling Under run panels carry their own data-bucr* tags (kept apart
    // from data-cr* so they never match a main chart run panel for the same
    // key); remember them too, and whether the "With chart" view was on.
    const openBuPanels = [];
    document.querySelectorAll('.bu-cr-row.open .bu-cr-panel[data-bucrtype][data-bucrkey]').forEach(panel => {
      const combined = panel.querySelector('.bu-cr-view-combined');
      openBuPanels.push({ type: panel.dataset.bucrtype, key: panel.dataset.bucrkey, combined: !!combined && combined.style.display !== 'none' });
    });

    renderAll();

    // Reopen the Bubbling Under panels (and their view) after the re-render
    openBuPanels.forEach(({ type, key, combined }) => {
      const panel = Array.from(document.querySelectorAll('.bu-cr-panel[data-bucrtype="' + type + '"]'))
        .find(p => p.dataset.bucrkey === key);
      const crRow = panel && panel.closest('.bu-cr-row');
      if (!crRow) return;
      crRow.classList.add('open');
      const btn = crRow.previousElementSibling && crRow.previousElementSibling.querySelector('.bu-cr-btn');
      if (btn) btn.classList.add('active');
      if (combined) {
        const segBtns = panel.querySelectorAll('.bu-cr-seg .cr-range-btn');
        if (segBtns[1]) toggleBuCombinedView(segBtns[1], true);
      }
    });

    // Restore open state for any panels that were open before the re-render
    openPanels.forEach(({ crtype, crkey }) => {
      const panel = document.querySelector(`.cr-panel[data-crtype="${crtype}"][data-crkey="${crkey}"]`);
      if (!panel) return;
      const crRow = panel.closest('.cr-row');
      if (!crRow) return;
      // Table panels are built on first open now (app.js, _crFillLazy)
      if (typeof _crFillLazy === 'function') _crFillLazy(crRow);
      crRow.classList.add('open');
      const mainRow = crRow.previousElementSibling;
      if (mainRow) {
        const btn = mainRow.querySelector('.cr-toggle-btn');
        if (btn) btn.classList.add('active');
      }
    });
  }
  // Re-render the album modal's chart run section if it's open
  const albumModal = document.getElementById('albumModal');
  if (albumModal?.classList.contains('open') && typeof _currentAlbumKey !== 'undefined' && _currentAlbumKey) {
    const crEl = document.getElementById('albumModalChartRun');
    if (crEl && typeof chartRunData !== 'undefined' && chartRunData?.result?.albums?.[_currentAlbumKey]) {
      crEl.innerHTML = `<div class="cr-album-run"><div class="cr-stats cr-stats-sum">${crStats('albums', _currentAlbumKey, chartRunData.period)}</div>${crBoxesHTML('albums', _currentAlbumKey)}</div>`;
    }
  }

  // Re-render the community board if active (its labels and dates are built in JS)
  if (typeof currentPeriod !== 'undefined' && currentPeriod === 'board' && window.dcBoard) window.dcBoard.rerender();
  // ...and The Dank 100, for the same reason
  if (typeof currentPeriod !== 'undefined' && currentPeriod === 'dank100' && window.dcDank100) window.dcDank100.rerender();
  // ...and World Charts
  if (typeof currentPeriod !== 'undefined' && currentPeriod === 'worldcharts' && window.dcWorldCharts) window.dcWorldCharts.rerender();
  // ...and its invite banner on the chart tabs
  if (window.dcDank100) window.dcDank100.renderPromo();

  // Re-render records tab if active (renderAll does not handle the records period)
  if (typeof currentPeriod !== 'undefined' && currentPeriod === 'records' && typeof buildRecords === 'function') {
    buildRecords();
  }

  // Re-render graphs tab if active (renderAll does not handle the graphs period)
  if (typeof currentPeriod !== 'undefined' && currentPeriod === 'graphs' && typeof renderGraphs === 'function') {
    renderGraphs();
  }
  // Refresh the Stats Labels buttons' tooltips in the new language. Done on
  // every tab, not only Stats: they are icons now, so the tooltip is the only
  // place their words live and nothing else would update it.
  if (typeof updateLabelButton === 'function') {
    if (typeof gTotalVolumeLabels !== 'undefined') updateLabelButton('gTotalVolumeLabelsBtn', gTotalVolumeLabels);
  }

  // Update theme label with new language
  const currentTheme = localStorage.getItem('dankcharts-theme') || 'navy-dark';
  const themeLabel = document.getElementById('themeLabel');
  if (themeLabel) {
    const normalizedTheme = currentTheme.includes('-') ? currentTheme : currentTheme + '-dark';
    const labelKey = 'tooltip_theme_' + normalizedTheme.replace('-', '_');
    themeLabel.textContent = t(labelKey) || t('tooltip_theme_navy_dark');
  }
}

// ─── INITIALIZE ───────────────────────────────────────────────────────────────
(function () {
  try {
    const saved = localStorage.getItem('dankcharts-lang');
    if (saved && DC_LANGS.includes(saved)) currentLang = saved;
  } catch (e) { }
})();

// Apply saved language to static DOM elements once the page is ready
document.addEventListener('DOMContentLoaded', function () {
  document.documentElement.lang = currentLang;
  document.querySelectorAll('.lang-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.lang === currentLang);
  });
  applyI18n();
  // The inline script normally loads the saved language before this point. If
  // it did not (blocked, or a page without that script), fetch it now and
  // switch over fully once it is in.
  if (!DC_I18N_LOADED[currentLang]) {
    const lang = currentLang;
    dcEnsureLang(lang, () => { if (DC_I18N_LOADED[lang] && currentLang === lang) setLanguage(lang); });
  }
});
